head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    tabControl1.showTab(0);
    tabControl1.showTab(1);
    tabControl1.hideTab(2);
    tabControl1.hideTab(3);
    tabControl1.hideTab(4);
};
scwin.trigger2_onclick = function(e) {
    $p.log("11111111111");
    tabControl1.hideTab(0);
    $p.log("2222222222");
    tabControl1.hideTab(1);
    $p.log("333333333333");
    debugger;
    tabControl1.showTab(2);
    $p.log("44444444444");
    tabControl1.showTab(3);
    $p.log("555555555555");
    tabControl1.showTab(4);
    $p.log("66666666666666");
};
scwin.trigger3_onclick = function(e) {
    tabControl1.showTab(0);
    tabControl1.showTab(1);
    tabControl1.showTab(2);
    tabControl1.showTab(3);
    tabControl1.showTab(4);
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
